# Randomize the 3-digit block and the gap; enforce d1 != 0 and digits < base.
def find_min_n(base, d1, d2, d3, gap, nmax=20000):
    A = d1*base*base + d2*base + d3
    B = base**3
    for n in range(2, nmax+1):
        if math.gcd(n, base) != 1:
            continue
        # Integer interval [L, R] of r such that floor(B*r/n) = A
        L = (A*n + B - 1)//B
        R = ((A+1)*n - 1)//B
        if R < L:
            continue
        k = pow(base, gap, n)
        # search for r in [L,R] with gcd(r,n)=1 and k*r mod n in [L,R]
